"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The a key to a locker Case', 'author': 'Signature original', 'genre': 'Underworld', 'chapters': [{'n': 1, 'title': 'The Client', 'text': "That night Frank Delaney stood at the office window, watching the neon bleed into the wet street. a key to a locker sat in the safe. Outside, Neon Row did what it always did: it waited.\n\n'I need you to find out what this means,' the client said, laying a key to a locker on the desk like a bet. Frank Delaney had seen a hundred such objects. They all meant the same thing: somebody was lying, and somebody was going to bleed.\n\nDoc Ellison whistled when they heard. 'the corrupt councilman is mixed up in this,' Doc Ellison said. 'You know what happened to the last shamus who crossed the corrupt councilman.' Frank Delaney knew. Everyone knew."}, {'n': 2, 'title': 'The Streets Talk', 'text': "Doc Ellison drove the getaway when it went sour, which it did, because it always does. Bullets and rain on the windshield. Doc Ellison laughed the whole way. 'You owe me,' Doc Ellison said.\n\nFrank Delaney started where every case starts: the bars. Lou poured whiskey and talked about the corrupt councilman's new operation, about money moving through Neon Row like blood through a bad heart.\n\nThe address led to Neon Row's underbelly — a locker, a ledger, a man who didn't want to talk until Frank Delaney showed him a key to a locker. Then he talked like a river, and Frank Delaney wrote it all down."}, {'n': 3, 'title': "The Dame's Story", 'text': "She came back at midnight — the client, or the woman behind the client. Her story changed the way stories do when the truth puts on its coat. a key to a locker, she admitted, was stolen. From the corrupt councilman.\n\n'Why should I trust you?' Frank Delaney asked. She had no answer that wasn't tears, and Frank Delaney had stopped buying tears during the war. But a key to a locker was real, and the ledger was real, and that was enough.\n\nThey tailed the corrupt councilman's fixer to a warehouse on the waterfront. What they saw there turned Frank Delaney's stomach: not just money, but the machinery of Neon Row's misery, oiled and humming."}, {'n': 4, 'title': 'The Squeeze', 'text': "The dame vanished. Of course she did. Frank Delaney found her scarf in the office, red as a warning, and underneath it a note: 'Forgive me. They have my brother.' So that was the price. Everyone has one.\n\nFrank Delaney sat up all night with a key to a locker and the photographs and the whiskey going untouched. By dawn there was a plan. It wasn't a good plan. It was the only plan.\n\nthe corrupt councilman squeezed back. First the office: tossed, the safe cracked, a key to a locker's copy gone — but Frank Delaney keeps the originals where no one looks. Then Doc Ellison: a warning delivered with fists in an alley off Neon Row."}, {'n': 5, 'title': 'The Confrontation', 'text': "It went down the way it always goes: shouting, threats, a gun that Frank Delaney was faster than. When the police took the corrupt councilman out, Neon Row seemed to exhale, like a drunk finally telling the truth.\n\nFrank Delaney walked into the corrupt councilman's office at noon, when Neon Row was bright and honest-looking, which made the lies inside seem darker. a key to a locker went on the desk. The photographs went on the desk. The truth went on the desk.\n\n'You're finished,' Frank Delaney said. the corrupt councilman smiled the smile of someone who has bought judges. 'Am I?' Then Doc Ellison opened the door with the district attorney, and Ruby, and the dame's brother, alive, and the smile died."}, {'n': 6, 'title': 'Last Call', 'text': "The phone rang. Frank Delaney picked it up. 'Frank Delaney Investigations,' Frank Delaney said, and listened, and smiled the thin smile of someone who knows exactly how much trouble costs. 'loyalty in a dirty town. I'll take the case.'\n\nLou poured a double on the house. Ruby sang the song she only sings when she means it. Doc Ellison's ribs were taped, but Doc Ellison drank anyway, doctor's orders being for other people.\n\nNeon Row kept being Neon Row: rain, neon, lies, and now and then — now and then — a little justice, served neat, no ice. Frank Delaney could live with that. Frank Delaney had lived with worse."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

